#!/usr/bin/env python3
from docx import Document
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

def set_rtl(p):
    pPr=p._p.get_or_add_pPr()
    if pPr.find(qn('w:bidi')) is None:
        b=pPr.find(qn('w:bidi'))
        b= OxmlElement('w:bidi'); b.set(qn('w:val'),'1'); pPr.append(b)
    jc=pPr.find(qn('w:jc'))
    if jc is None:
        jc=OxmlElement('w:jc'); pPr.append(jc)
    jc.set(qn('w:val'),'right')
    p.alignment=WD_ALIGN_PARAGRAPH.RIGHT
def set_font(run,name="B Nazanin",size=13,bold=False,color=None,italic=False):
    run.font.name=name; run.font.size=Pt(size); run.bold=bold; run.italic=italic
    if color: run.font.color.rgb=RGBColor.from_string(color)
    r=run._element; rPr=r.get_or_add_rPr()
    rFonts=rPr.find(qn('w:rFonts'))
    if rFonts is None: rFonts=OxmlElement('w:rFonts'); rPr.append(rFonts)
    rFonts.set(qn('w:ascii'),name); rFonts.set(qn('w:hAnsi'),name); rFonts.set(qn('w:cs'),name); rFonts.set(qn('w:eastAsia'),name)
def sp(p,before=0,after=6,ls=1.45):
    pf=p.paragraph_format; pf.space_before=Pt(before); pf.space_after=Pt(after); pf.line_spacing=ls; pf.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    pPr=p._p.get_or_add_pPr()
    if pPr.find(qn('w:widowControl')) is None:
        w=OxmlElement('w:widowControl'); w.set(qn('w:val'),'1'); pPr.append(w)
def add_heading(doc,text,level=1,color="8B1A1A",size=15):
    p=doc.add_paragraph(); set_rtl(p); r=p.add_run(text); set_font(r,"B Nazanin",size,True,color); sp(p,before=16,after=8)
    if level==1:
        pPr=p._p.get_or_add_pPr(); bdr=OxmlElement('w:pBdr'); b=OxmlElement('w:bottom'); b.set(qn('w:val'),'single'); b.set(qn('w:sz'),'4'); b.set(qn('w:space'),'6'); b.set(qn('w:color'),color); bdr.append(b); pPr.append(bdr)
        shd=OxmlElement('w:shd'); shd.set(qn('w:val'),'clear'); shd.set(qn('w:color'),'auto'); shd.set(qn('w:fill'),'FFF2F2'); pPr.append(shd)
    return p
def add_sub(doc,text,size=12.5,color="333333"):
    p=doc.add_paragraph(); set_rtl(p); r=p.add_run(text); set_font(r,"B Nazanin",size,True,color); sp(p,before=8,after=4); return p
def add_p(doc,text,size=11.5,bold=False,color="1A1A1A",after=6,italic=False):
    p=doc.add_paragraph(); set_rtl(p); r=p.add_run(text); set_font(r,"B Nazanin",size,bold,color,italic); sp(p,after=after); return p
def add_bullet(doc,text,size=11):
    p=doc.add_paragraph(); set_rtl(p); p.clear(); r=p.add_run("•  "+text); set_font(r,"B Nazanin",size,color="1A1A1A"); sp(p,after=3,ls=1.35); p.paragraph_format.right_indent=Cm(1); return p
def add_quote(doc,text,source="",size=11,color="004400"):
    p=doc.add_paragraph(); set_rtl(p); pPr=p._p.get_or_add_pPr(); bdr=OxmlElement('w:pBdr'); rt=OxmlElement('w:right'); rt.set(qn('w:val'),'single'); rt.set(qn('w:sz'),'12'); rt.set(qn('w:space'),'8'); rt.set(qn('w:color'),'8B1A1A'); bdr.append(rt); pPr.append(bdr); shd=OxmlElement('w:shd'); shd.set(qn('w:val'),'clear'); shd.set(qn('w:color'),'auto'); shd.set(qn('w:fill'),'F9F5E8'); pPr.append(shd); r=p.add_run(text); set_font(r,"B Nazanin",size,italic=True,color=color)
    if source: r=p.add_run("  — "+source); set_font(r,"B Nazanin",9,color="666666")
    sp(p,before=6,after=8); pf=p.paragraph_format; pf.right_indent=Cm(0.8); pf.left_indent=Cm(0.5); return p

path="/home/user/Hadii/کتاب_ایام_فاطمیه/ایام_فاطمیه_کتاب_جامع_طلاب.docx"
doc=Document(path)
print(f"Before {len(doc.paragraphs)} paras")

# Add substantial new material
add_heading(doc, "فصل پانزدهم: فاطمیه در سیرهٔ علما و مراجع تقلید", level=1, size=15)
add_p(doc, "فاطمیه، مکتب تربیت علما بوده است. بسیاری از مراجع بزرگ، در ایام فاطمیه گریه می‌کردند و مجلس می‌گرفتند. نقل است آیت‌الله العظمی بروجردی قدس‌سره در دههٔ فاطمیه، درس خارج را تعطیل می‌کرد و خود در مجلس روضه شرکت می‌کرد و با صدای بلند گریه می‌کرد. شاگردان می‌گویند وقتی روضهٔ «بین درب و دیوار» خوانده می‌شد، ایشان چنان می‌گریست که شانه‌هایش می‌لرزید.")
add_p(doc, "آیت‌الله العظمی خمینی قدس‌سره نیز فاطمیه را «ایام الله» می‌نامید و می‌فرمود: «ما هر چه داریم از فاطمهٔ زهرا داریم». ایشان در وصیت‌نامهٔ الهی سیاسی خود، به توسل به حضرت زهرا توصیه کرده است. آیت‌الله بهجت قدس‌سره هر روز زیارت حضرت زهرا را می‌خواند و می‌فرمود: «اگر می‌خواهید عاقبت به خیر شوید، دست از دامن فاطمه برندارید». این سیره، درس بزرگی برای طلاب است: اگر می‌خواهی عالم ربانی شوی، فاطمی باش.")
add_sub(doc, "۱۵ـ۱. خاطراتی از علما")
add_bullet(doc, "علامه امینی، صاحب الغدیر، بیست سال برای اثبات حقانیت علی، منابع اهل‌سنت را ورق زد و می‌گفت: «نوکر فاطمه‌ام و به عشق او الغدیر را نوشتم».")
add_bullet(doc, "شهید مطهری در آخرین سخنرانی پیش از شهادت، از فاطمیه گفت و فردا به شهادت رسید؛ گویی فاطمه او را به مهمانی برد.")
add_bullet(doc, "آیت‌الله قاضی طباطبایی می‌فرمود: «درِ رحمت خدا در فاطمیه باز است؛ هر کس در این ایام توبه کند، قطعاً پذیرفته می‌شود».")
add_bullet(doc, "آیت‌الله سید علی خامنه‌ای، هر سال در حسینیهٔ امام خمینی، مجلس فاطمیه می‌گیرد و خود مقتل می‌خواند؛ الگویی برای مسئولان که باید مردمی و فاطمی باشند.")
add_p(doc, "طلبهٔ عزیز! وقتی زندگی علما را می‌خوانی، می‌بینی محور همهٔ آنها فاطمیه است. پس تو نیز برنامهٔ سالانه‌ات را فاطمی کن؛ از فاطمیه تا فاطمیه، برای فاطمه کار کن. این برکت، درس و بحثت را هم نورانی می‌کند.")

add_heading(doc, "فصل شانزدهم: فاطمیه و انقلاب اسلامی؛ از قیام تا مقاومت", level=1, size=15)
add_p(doc, "پیوند فاطمیه و انقلاب اسلامی، پیوندی ناگسستنی است. امام خمینی قدس‌سره نهضت خود را با نام فاطمه آغاز کرد؛ در سال ۱۳۴۲، در مدرسهٔ فیضیه، وقتی از فاطمه گفت، مردم به جوش آمدند. شعار «یا زهرا» در جبهه‌های جنگ، رمز عملیات بود: یا زهرا، فاطمیون، زینبیون. شهدا با نام فاطمه شهید شدند و مادران شهدا با تأسی به فاطمه، فرزندانشان را بدرقه کردند.")
add_p(doc, "امروز نیز جبههٔ مقاومت، جبههٔ فاطمی است. زنان غزه که در زیر بمباران، حجاب فاطمی را حفظ می‌کنند، رهروان فاطمه‌اند. حزب‌الله لبنان، پرچمش را مزین به «یا فاطمة الزهراء» کرده است. این نشان می‌دهد فاطمیه، فقط تاریخ نیست؛ جغرافیای مقاومت است. هر جا ظلمی باشد، نام فاطمه پرچم مظلومان است. به همین دلیل، دشمنان اسلام از فاطمیه می‌ترسند و می‌خواهند آن را کم‌رنگ کنند؛ اما کور خوانده‌اند؛ فاطمیه، نور خداست و خاموش نمی‌شود.")
add_sub(doc, "۱۶ـ۱. وظیفهٔ ما در جنگ نرم")
add_p(doc, "امروز جنگ، جنگ رسانه است. دشمن با سریال و فیلم، حجاب فاطمی را تمسخر می‌کند. وظیفهٔ طلبهٔ مجتهد تاریخ آن است که با قلم، منبر و فضای مجازی، از حریم فاطمه دفاع کند. یک کلیپ یک‌دقیقه‌ای از خطبهٔ فدکیه، می‌تواند هزار جوان را بیدار کند. یک پوستر زیبا از «کوثر»، می‌تواند یک مدرسه را فاطمی کند. از ابزار روز غافل نشو؛ فاطمه، بانوی همهٔ عصرهاست، پس باید به زبان عصر تبلیغ شود. پیشنهاد می‌شود هر طلبه، یک کانال فاطمی در ایتا یا بله داشته باشد و در فاطمیه، هر روز یک حدیث منتشر کند.")

add_heading(doc, "فصل هفدهم: سبک زندگی فاطمی برای خانوادهٔ امروز", level=1, size=15)
add_p(doc, "خانوادهٔ امروز در بحران است؛ آمار طلاق، اعتیاد، بی‌بندوباری و افسردگی بالا رفته است. راه نجات، بازگشت به سبک زندگی فاطمی است. در این فصل، هفت اصل خانوادهٔ فاطمی را مرور می‌کنیم که هر طلبه باید در جلسات مشاوره و منبر بگوید:")
add_sub(doc, "اصل اول: ساده‌زیستی")
add_p(doc, "جهیزیهٔ فاطمه، چند ظرف سفالی بود. مهریه‌اش ۵۰۰ درهم بود. پیامبر به علی فرمود: «بهترین زنان امت، کم‌مهریه‌ترین آنهاست». امروز چشم و هم‌چشمی، کمر خانواده‌ها را شکسته است. طلبه باید فرهنگ «ازدواج آسان» را ترویج کند؛ عقد در مسجد، ولیمهٔ ساده، جهیزیهٔ مختصر. هر عقد آسان، یک قدم به سوی جامعهٔ فاطمی است.")
add_sub(doc, "اصل دوم: عبادت خانوادگی")
add_p(doc, "خانهٔ فاطمه، مسجد بود. حسن و حسین، نماز شب را از مادر آموختند. امام حسن می‌گوید مادرم شب جمعه تا صبح عبادت می‌کرد. امروز خانواده‌ها باید نماز جماعت در خانه داشته باشند؛ پدر امام جماعت، مادر و فرزندان مأموم. این نماز، خانه را نورانی می‌کند و شیطان را دور می‌کند. پیامبر فرمود: «خانه‌ای که در آن قرآن خوانده شود، برای اهل آسمان می‌درخشد».")
add_sub(doc, "اصل سوم: حجاب و عفاف")
add_p(doc, "فاطمه، الگوی حجاب است. وقتی نابینایی وارد شد، فاطمه حجاب کرد؛ پیامبر پرسید چرا؟ فرمود: «اگر او مرا نمی‌بیند، من او را می‌بینم». این اوج عفاف است. امروز دشمن، حجاب را نشانهٔ عقب‌ماندگی می‌خواند، اما ما می‌گوییم حجاب، تاج کرامت زن است. حجاب فاطمی، یعنی چادر مشکی، متانت، و پرهیز از خودنمایی در فضای مجازی. زن فاطمی، در کوچه و دانشگاه، زینبی است.")
add_sub(doc, "اصل چهارم: همسرداری و احترام متقابل")
add_p(doc, "فاطمه و علی، هرگز با هم تندی نکردند. علی می‌فرماید: «هیچ‌گاه فاطمه را خشمگین نکردم و او نیز مرا خشمگین نکرد». رازش در احترام بود. فاطمه، علی را «یا اباالحسن» صدا می‌زد و علی، فاطمه را «یا بنت رسول‌الله». این ادب، امروز گم شده است. زوجین باید همدیگر را با القاب محترم صدا کنند، نه با توهین. طلاق عاطفی، از بی‌احترامی شروع می‌شود.")
add_sub(doc, "اصل پنجم: تربیت فرزند با قصهٔ اهل‌بیت")
add_p(doc, "فاطمه برای حسن و حسین قصهٔ پیامبران می‌گفت. امروز کودکان ما با کارتون‌های غربی بزرگ می‌شوند. باید قصهٔ فاطمی را جایگزین کرد؛ قصهٔ فدک، قصهٔ مباهله، قصهٔ تسبیح فاطمه. هر شب پیش از خواب، یک قصهٔ فاطمی برای فرزند بگو؛ این قصه، تا آخر عمر در ذهنش می‌ماند و او را بیمه می‌کند.")
add_sub(doc, "اصل ششم: قناعت و کار")
add_p(doc, "فاطمه با دست خود آرد می‌کرد، نان می‌پخت، و لباس می‌دوخت. او الگوی زن کارآفرین است، نه زن مصرف‌گرا. امروز اقتصاد مقاومتی با قناعت فاطمی محقق می‌شود؛ خرید کالای ایرانی، پرهیز از اسراف، و قناعت در خوراک و پوشاک. پیامبر فرمود: «ما عال من اقتصد»؛ هر کس میانه‌روی کند، فقیر نمی‌شود.")
add_sub(doc, "اصل هفتم: دفاع از ولایت")
add_p(doc, "مهم‌ترین اصل خانوادهٔ فاطمی، ولایت‌مداری است. فاطمه برای دفاع از ولایت علی، جان داد. خانوادهٔ امروز نیز باید ولایت‌مدار باشد؛ یعنی گوش به فرمان ولی‌فقیه، حاضر در صحنهٔ انقلاب، و مدافع نظام اسلامی. خانوادهٔ بی‌تفاوت، خانوادهٔ فاطمی نیست. هر خانواده باید یک «قرار فاطمی» داشته باشد: شرکت در انتخابات، راهپیمایی، و کمک به محرومان.")

add_heading(doc, "پیوست ۵: واژه‌نامهٔ فاطمی (برای طلاب مبتدی)", level=1, size=14)
add_p(doc, "برای فهم بهتر متون، معنای برخی واژگان مهم را می‌آوریم:")
add_bullet(doc, "بتول: بریده از آلودگی و دنیاپرستی؛ لقب فاطمه و مریم، اما بتولی فاطمه کامل‌تر است.")
add_bullet(doc, "کوثر: خیر فراوان؛ در تفسیر، به فاطمه و نسل پربرکت او تفسیر شده است.")
add_bullet(doc, "فدک: دهکده‌ای حاصلخیز در شمال مدینه که پیامبر آن را به فاطمه بخشید و بعد غصب شد.")
add_bullet(doc, "سقیفه: سایبان محل اجتماع انصار در مدینه که خلافت ابوبکر در آنجا شکل گرفت.")
add_bullet(doc, "فلته: کار ناگهانی و بدون مشورت؛ عمر دربارهٔ بیعت ابوبکر گفت: «کانت فلتة».")
add_bullet(doc, "مصحف فاطمه: کتابی که جبرئیل پس از رحلت پیامبر بر فاطمه املا کرد و علی نوشت؛ نزد ائمه است و ربطی به قرآن ندارد.")
add_bullet(doc, "تسبیح فاطمه: ذکر ۳۴ الله‌اکبر، ۳۳ الحمدلله، ۳۳ سبحان‌الله؛ هدیهٔ پیامبر به دخترش.")
add_bullet(doc, "صدیقهٔ کبری: بسیار راستگو؛ لقب فاطمه که حتی دشمنان به صداقتش گواهی دادند.")
add_bullet(doc, "ام‌ابیها: مادر پدرش؛ کنایه از مهر مادرانهٔ فاطمه به پیامبر.")
add_bullet(doc, "سیده نساء العالمین: سرور زنان جهان؛ مقامی که پیامبر برای فاطمه اثبات کرد.")

add_heading(doc, "پیوست ۶: گاه‌شمار فاطمیه (برای نصب در مسجد)", level=1, size=14)
add_p(doc, "این گاه‌شمار را چاپ و در مسجد نصب کنید تا مردم بدانند هر روز چه مناسبتی است:")
add_bullet(doc, "۲۸ صفر: رحلت پیامبر اکرم صلی‌الله‌علیه‌وآله - آغاز حزن فاطمه")
add_bullet(doc, "۱ ربیع‌الاول تا ۱۲ جمادی‌الاول: ایام آماده‌سازی؛ مطالعهٔ خطبهٔ فدکیه و آماده‌سازی هیئت")
add_bullet(doc, "۱۳ جمادی‌الاول (۷۵ روز): شهادت به روایت اول - فاطمیهٔ اول - اوج عزاداری")
add_bullet(doc, "۱۴-۱۵ جمادی‌الاول: ادامهٔ عزاداری و اطعام")
add_bullet(doc, "۱۶ جمادی‌الاول تا ۲ جمادی‌الثانی: دههٔ دوم - تبلیغ چهره به چهره، دیدار سادات")
add_bullet(doc, "۳ جمادی‌الثانی (۹۵ روز): شهادت به روایت دوم - فاطمیهٔ دوم - دستهٔ بزرگ")
add_bullet(doc, "۴-۵ جمادی‌الثانی: اختتامیه و جمع‌بندی؛ تجدید بیعت با مهدی عجل‌الله‌فرجه")
add_p(doc, "در تمام این ایام، پرچم مشکی بر سر در خانه‌ها، مساجد و مغازه‌ها نصب شود؛ شهر باید رنگ فاطمی بگیرد. شهرداری‌ها موظفند شهر را سیاه‌پوش کنند؛ این کمترین احترام به مادر شیعه است.")

add_heading(doc, "پیوست ۷: منابع دیجیتال و نرم‌افزارهای پیشنهادی", level=1, size=14)
add_p(doc, "طلبهٔ امروز باید دیجیتال باشد. این منابع را نصب و استفاده کن:")
add_bullet(doc, "نرم‌افزار نورالجنان: شامل مفاتیح، صحیفهٔ سجادیه و زیارات با ترجمه و صوت.")
add_bullet(doc, "نرم‌افزار جامع الاحادیث نور: جستجوی حدیث فاطمی در ۳۰۰ کتاب حدیثی.")
